use hy_check::check_file;
use hy_syntax::parse_file;

fn codes(src: &str) -> Vec<String> { check_file(&parse_file("inline.hy", src).expect("parse")).diagnostics.into_iter().map(|d| d.code).collect() }

#[test]
fn transitive_multireturn_forwarding_freezes_shared_move_peers() {
    for src in [
        "struct bundle { dst map[string]map[string]int\n m map[string]int }\nfn pack_with_tag(dst map[string]map[string]int, m map[string]int) (int, bundle) { return 0, bundle{dst: dst, m: m} }\nfn link_second(tag int, b bundle) { _ = tag\n b.dst[\"slot\"] = b.m }\nfn outer(dst map[string]map[string]int, m map[string]int) { link_second(pack_with_tag(dst, m)) }\nfn worker(m map[string]int) { m[\"k\"] = 99 }\nfn main() {\n dst := map[string]map[string]int{}\n m := map[string]int{\"k\": 1}\n outer(dst, m)\n task worker(move m)\n dst[\"slot\"][\"k\"] = 42\n}\n",
        "fn pair_three(dst map[string][]int, src []int) (int, map[string][]int, []int) { return 0, dst, src }\nfn link_two_slots(tag int, dst map[string][]int, src []int) { _ = tag\n dst[\"k\"] = src }\nfn outer(dst map[string][]int, src []int) { link_two_slots(pair_three(dst, src)) }\nfn consume(xs []int) { xs[0] = 99 }\nfn main() {\n dst := map[string][]int{}\n src := []int{1, 2, 3}\n outer(dst, src)\n task consume(move src)\n dst[\"k\"][0] = 42\n}\n",
        "struct bundle { dst map[string]map[string]int\n m map[string]int }\nfn link_second(tag int, b bundle) { _ = tag\n b.dst[\"slot\"] = b.m }\nfn outer(dst map[string]map[string]int, m map[string]int) {\n pack := fn(d map[string]map[string]int, s map[string]int) (int, bundle) { return 0, bundle{dst: d, m: s} }\n link_second(pack(dst, m))\n}\nfn worker(m map[string]int) { m[\"k\"] = 99 }\nfn main() {\n dst := map[string]map[string]int{}\n m := map[string]int{\"k\": 1}\n outer(dst, m)\n task worker(move m)\n dst[\"slot\"][\"k\"] = 42\n}\n",
    ] { assert!(codes(src).iter().any(|c| c == "HYB-E3003")); }
}
#[test]
fn non_ident_callees_forward_multireturn_parameter_stores() {
    for src in [
        "struct sink {}\nstruct bundle { dst map[string]map[string]int\n m map[string]int }\nfn pack_with_tag(dst map[string]map[string]int, m map[string]int) (int, bundle) { return 0, bundle{dst: dst, m: m} }\nfn (s sink) link_second(tag int, b bundle) { _ = s\n _ = tag\n b.dst[\"slot\"] = b.m }\nfn worker(m map[string]int) { m[\"k\"] = 99 }\nfn main() {\n s := sink{}\n dst := map[string]map[string]int{}\n m := map[string]int{\"k\": 1}\n s.link_second(pack_with_tag(dst, m))\n task worker(move m)\n dst[\"slot\"][\"k\"] = 42\n}\n",
        "struct sink {}\nstruct bundle { dst map[string]map[string]int\n m map[string]int }\nfn pair_recv_tag_bundle(s sink, dst map[string]map[string]int, m map[string]int) (sink, int, bundle) { return s, 0, bundle{dst: dst, m: m} }\nfn (s sink) link_second(tag int, b bundle) { _ = s\n _ = tag\n b.dst[\"slot\"] = b.m }\nfn worker(m map[string]int) { m[\"k\"] = 99 }\nfn main() {\n s := sink{}\n dst := map[string]map[string]int{}\n m := map[string]int{\"k\": 1}\n sink.link_second(pair_recv_tag_bundle(s, dst, m))\n task worker(move m)\n dst[\"slot\"][\"k\"] = 42\n}\n",
        "struct bundle { dst map[string]map[string]int\n m map[string]int }\nfn pack_with_tag(dst map[string]map[string]int, m map[string]int) (int, bundle) { return 0, bundle{dst: dst, m: m} }\nfn worker(m map[string]int) { m[\"k\"] = 99 }\nfn main() {\n dst := map[string]map[string]int{}\n m := map[string]int{\"k\": 1}\n f := fn(tag int, b bundle) { _ = tag\n b.dst[\"slot\"] = b.m }\n f(pack_with_tag(dst, m))\n task worker(move m)\n dst[\"slot\"][\"k\"] = 42\n}\n",
        "struct bundle { dst map[string]map[string]int\n m map[string]int }\nfn pack_with_tag(dst map[string]map[string]int, m map[string]int) (int, bundle) { return 0, bundle{dst: dst, m: m} }\nfn worker(m map[string]int) { m[\"k\"] = 99 }\nfn main() {\n dst := map[string]map[string]int{}\n m := map[string]int{\"k\": 1}\n (fn(tag int, b bundle) { _ = tag\n b.dst[\"slot\"] = b.m })(pack_with_tag(dst, m))\n task worker(move m)\n dst[\"slot\"][\"k\"] = 42\n}\n",
    ] { assert!(codes(src).iter().any(|c| c == "HYB-E3003")); }
}
#[test]
fn transitive_multireturn_forwarding_propagates_non_owned_param_origin() {
    for src in [
        "struct bundle { dst map[string]map[string]int\n m map[string]int }\nfn pack_with_tag(dst map[string]map[string]int, m map[string]int) (int, bundle) { return 0, bundle{dst: dst, m: m} }\nfn link_second(tag int, b bundle) { _ = tag\n b.dst[\"slot\"] = b.m }\nfn outer(dst map[string]map[string]int, m map[string]int) { link_second(pack_with_tag(dst, m)) }\nfn consume_nested(dst map[string]map[string]int) { dst[\"slot\"][\"k\"] = 99 }\nfn leak(borrowed map[string]int) {\n dst := map[string]map[string]int{}\n outer(dst, borrowed)\n task consume_nested(move dst)\n}\nfn main() { m := map[string]int{\"k\": 1}\n leak(m) }\n",
        "struct sink {}\nstruct bundle { dst map[string]map[string]int\n m map[string]int }\nfn pack_with_tag(dst map[string]map[string]int, m map[string]int) (int, bundle) { return 0, bundle{dst: dst, m: m} }\nfn (s sink) link_second(tag int, b bundle) { _ = s\n _ = tag\n b.dst[\"slot\"] = b.m }\nfn consume_nested(dst map[string]map[string]int) { dst[\"slot\"][\"k\"] = 99 }\nfn leak(borrowed map[string]int) {\n s := sink{}\n dst := map[string]map[string]int{}\n s.link_second(pack_with_tag(dst, borrowed))\n task consume_nested(move dst)\n}\nfn main() { m := map[string]int{\"k\": 1}\n leak(m) }\n",
    ] { assert!(codes(src).iter().any(|c| c == "HYB-E3004")); }
}
#[test]
fn transitive_and_non_ident_multireturn_forwarding_rejects_const_writes() {
    for (src, n) in [
        ("const shared = map[string]int{\"k\": 1}\nfn pair_int_map(m map[string]int) (int, map[string]int) { return 0, m }\nfn write_second(tag int, m map[string]int) { m[\"k\"] = tag + 99 }\nfn outer_const(m map[string]int) { write_second(pair_int_map(m)) }\nfn main() { outer_const(shared) }\n", 1),
        ("const shared = map[string]int{\"k\": 1}\nstruct bundle { dst map[string]map[string]int\n m map[string]int }\nfn pack_with_tag(dst map[string]map[string]int, m map[string]int) (int, bundle) { return 0, bundle{dst: dst, m: m} }\nfn link_second(tag int, b bundle) { _ = tag\n b.dst[\"slot\"] = b.m }\nfn outer_alias_write(m map[string]int) {\n dst := map[string]map[string]int{}\n link_second(pack_with_tag(dst, m))\n dst[\"slot\"][\"k\"] = 99\n}\nfn main() { outer_alias_write(shared) }\n", 1),
        ("const shared = map[string]int{\"k\": 1}\nstruct sink {}\nfn pair_recv_int_map(s sink, m map[string]int) (sink, int, map[string]int) { return s, 0, m }\nfn (s sink) write_second(tag int, m map[string]int) { _ = s\n m[\"k\"] = tag + 99 }\nfn main() { s := sink{}\n sink.write_second(pair_recv_int_map(s, shared)) }\n", 1),
        ("const shared = map[string]int{\"k\": 1}\nstruct sink {}\nfn pair_int_map(m map[string]int) (int, map[string]int) { return 0, m }\nfn (s sink) write_second(tag int, m map[string]int) { _ = s\n m[\"k\"] = tag + 99 }\nfn outer_method(m map[string]int) { s := sink{}\n s.write_second(pair_int_map(m)) }\nfn main() { s := sink{}\n s.write_second(pair_int_map(shared))\n outer_method(shared) }\n", 2),
        ("const shared = map[string]int{\"k\": 1}\nfn pair_int_map(m map[string]int) (int, map[string]int) { return 0, m }\nfn outer_fnlit(m map[string]int) { (fn(tag int, inner map[string]int) { inner[\"k\"] = tag + 99 })(pair_int_map(m)) }\nfn main() { (fn(tag int, inner map[string]int) { inner[\"k\"] = tag + 99 })(pair_int_map(shared))\n outer_fnlit(shared) }\n", 2),
        ("const shared = map[string]int{\"k\": 1}\nstruct holder { dst map[string]map[string]int }\nstruct mutator { m map[string]int }\nfn pair_holder_map(h holder, m map[string]int) (holder, map[string]int) { return h, m }\nfn (h holder) store_into_recv(m map[string]int) { h.dst[\"slot\"] = m }\nfn pair_mutator_tag(x mutator, tag int) (mutator, int) { return x, tag }\nfn (x mutator) write_recv(tag int) { x.m[\"k\"] = tag + 99 }\nfn outer_recv_alias(m map[string]int) { h := holder{dst: map[string]map[string]int{}}\n holder.store_into_recv(pair_holder_map(h, m))\n h.dst[\"slot\"][\"k\"] = 99 }\nfn outer_recv_mut(m map[string]int) { x := mutator{m: m}\n mutator.write_recv(pair_mutator_tag(x, 0)) }\nfn main() { outer_recv_alias(shared)\n outer_recv_mut(shared) }\n", 2),
    ] { assert_eq!(codes(src).iter().filter(|c| *c == "HYB-E3006").count(), n); }
}
#[test]
fn multireturn_forwarding_invalidates_live_map_slot_loans() {
    for (src, n) in [
        ("struct svc { count int }\nfn pair_tag_map(m map[string]svc) (int, map[string]svc) { return 0, m }\nfn insert_second(tag int, m map[string]svc) { _ = tag\n m[\"b\"] = svc{count: 2} }\nfn outer_insert(m map[string]svc) { insert_second(pair_tag_map(m)) }\nfn direct_case() { m := map[string]svc{\"a\": svc{count: 1}}\n s := &m[\"a\"]\n insert_second(pair_tag_map(m))\n s.count = 99 }\nfn transitive_case() { m := map[string]svc{\"a\": svc{count: 1}}\n s := &m[\"a\"]\n outer_insert(m)\n s.count = 99 }\nfn main() { direct_case()\n transitive_case() }\n", 2),
        ("struct svc { count int }\nstruct box_sink {}\nfn pair_tag_map(m map[string]svc) (int, map[string]svc) { return 0, m }\nfn insert_second(tag int, m map[string]svc) { _ = tag\n m[\"b\"] = svc{count: 2} }\nfn (b box_sink) insert_second(tag int, m map[string]svc) { _ = b\n _ = tag\n m[\"b\"] = svc{count: 2} }\nfn outer_method_insert(m map[string]svc) { b := box_sink{}\n b.insert_second(pair_tag_map(m)) }\nfn method_direct() { b := box_sink{}\n m := map[string]svc{\"a\": svc{count: 1}}\n s := &m[\"a\"]\n b.insert_second(pair_tag_map(m))\n s.count = 99 }\nfn method_transitive() { m := map[string]svc{\"a\": svc{count: 1}}\n s := &m[\"a\"]\n outer_method_insert(m)\n s.count = 99 }\nfn inline_fnlit() { m := map[string]svc{\"a\": svc{count: 1}}\n s := &m[\"a\"]\n (fn(tag int, t map[string]svc) { _ = tag\n t[\"b\"] = svc{count: 2} })(pair_tag_map(m))\n s.count = 99 }\nfn captured_closure() { m := map[string]svc{\"a\": svc{count: 1}}\n s := &m[\"a\"]\n f := fn() { insert_second(pair_tag_map(m)) }\n f()\n s.count = 99 }\nfn main() { method_direct()\n method_transitive()\n inline_fnlit()\n captured_closure() }\n", 4),
        ("struct svc { count int }\nstruct box_sink {}\nfn pair_recv_tag_map(b box_sink, m map[string]svc) (box_sink, int, map[string]svc) { return b, 0, m }\nfn (b box_sink) insert_second(tag int, m map[string]svc) { _ = b\n _ = tag\n m[\"b\"] = svc{count: 2} }\nfn main() { b := box_sink{}\n m := map[string]svc{\"a\": svc{count: 1}}\n s := &m[\"a\"]\n box_sink.insert_second(pair_recv_tag_map(b, m))\n s.count = 99 }\n", 1),
        ("struct svc { count int }\nstruct mutator { m map[string]svc }\nfn pair_mutator_tag(x mutator, tag int) (mutator, int) { return x, tag }\nfn (x mutator) insert_recv(tag int) { _ = tag\n x.m[\"b\"] = svc{count: 2} }\nfn outer_a3(m map[string]svc) { x := mutator{m: m}\n mutator.insert_recv(pair_mutator_tag(x, 0)) }\nfn main() { m := map[string]svc{\"a\": svc{count: 1}}\n s := &m[\"a\"]\n outer_a3(m)\n s.count = 99 }\n", 1),
    ] { assert_eq!(codes(src).iter().filter(|c| *c == "HYB-E3102").count(), n); }
}
#[test]
fn readonly_and_primitive_multireturn_forwarding_remain_accepted() {
    for src in [
        "const shared = map[string]int{\"k\": 1}\nstruct probe {}\nfn id[t](x t) t { return x }\nfn pair_int_map(m map[string]int) (int, map[string]int) { return 7, m }\nfn pair_recv_int_map(r probe, m map[string]int) (probe, int, map[string]int) { return r, 7, m }\nfn read_second(tag int, m map[string]int) int { return tag + m[\"k\"] }\nfn (r probe) read_second(tag int, m map[string]int) int { _ = r\n return tag + m[\"k\"] }\nfn outer_read(m map[string]int) int {\n r := probe{}\n a := read_second(pair_int_map(m))\n b := probe.read_second(pair_recv_int_map(r, m))\n c := id(r).read_second(pair_int_map(m))\n d := (fn(tag int, inner map[string]int) int { return tag + inner[\"k\"] })(pair_int_map(m))\n return a + b + c + d\n}\nfn main() { _ = outer_read(shared) }\n",
        "struct svc { count int }\nstruct probe {}\nfn pair_tag_map(m map[string]svc) (int, map[string]svc) { return 1, m }\nfn pair_recv_tag_map(r probe, m map[string]svc) (probe, int, map[string]svc) { return r, 1, m }\nfn read_second(tag int, m map[string]svc) int { return tag + m[\"a\"].count }\nfn (r probe) read_second(tag int, m map[string]svc) int { _ = r\n return tag + m[\"a\"].count }\nfn outer_read(m map[string]svc) int { r := probe{}\n return read_second(pair_tag_map(m)) + probe.read_second(pair_recv_tag_map(r, m)) }\nfn main() {\n r := probe{}\n m := map[string]svc{\"a\": svc{count: 1}}\n s := &m[\"a\"]\n _ = read_second(pair_tag_map(m))\n _ = probe.read_second(pair_recv_tag_map(r, m))\n _ = outer_read(m)\n _ = (fn(tag int, inner map[string]svc) int { return tag + inner[\"a\"].count })(pair_tag_map(m))\n s.count = 99\n}\n",
        "fn pair_prim(xs []int, ys []int) (int, string) { return len(xs), \"ok\" }\nfn consume_prim(n int, label string) int { _ = label\n return n }\nfn outer_prim(xs []int, ys []int) int { return consume_prim(pair_prim(xs, ys)) }\nfn worker(ys []int) { ys[0] = 99 }\nfn main() {\n xs := []int{1, 2}\n ys := []int{3, 4}\n _ = outer_prim(xs, ys)\n task worker(move ys)\n xs[0] = 7\n}\n",
        "const shared = map[string]int{\"k\": 1}\nstruct mutator { self_map map[string]int }\nfn (x mutator) mutate_recv_only(m map[string]int) { _ = m\n x.self_map[\"k\"] = 99 }\nfn outer_shadowed(m map[string]int) { mutator := mutator{self_map: map[string]int{}}\n mutator.mutate_recv_only(m) }\nfn main() { outer_shadowed(shared) }\n",
    ] { assert_eq!(codes(src), Vec::<String>::new()); }
}
